package automagy.content;
import net.minecraft.core.BlockPos;
import net.minecraft.world.level.Level;
import net.minecraft.world.level.block.*;
import net.minecraft.world.level.block.entity.*;
import net.minecraft.world.level.block.state.BlockState;
public final class GolemWorkbenchBlock extends BaseEntityBlock implements thaumcraft.api.wands.IWandable {
 public GolemWorkbenchBlock(){super(Properties.of().strength(2.5f).sound(SoundType.WOOD).noOcclusion());}
 @Override public net.minecraft.world.InteractionResult use(BlockState state,Level level,BlockPos pos,net.minecraft.world.entity.player.Player player,net.minecraft.world.InteractionHand hand,net.minecraft.world.phys.BlockHitResult hit){if(!player.mayBuild())return net.minecraft.world.InteractionResult.FAIL;if(level.getBlockEntity(pos) instanceof GolemWorkbenchBlockEntity tile&&hit.getDirection().getAxis()!=net.minecraft.core.Direction.Axis.Y){var held=player.getItemInHand(hand);for(var entry:Content.WORKBENCH_UPGRADES.entrySet())if(held.is(entry.getValue().get())){if(!level.isClientSide&&tile.installUpgrade(entry.getKey(),hit.getDirection().get3DDataValue()-2)&&!player.getAbilities().instabuild)held.shrink(1);return net.minecraft.world.InteractionResult.sidedSuccess(level.isClientSide);}}if(!level.isClientSide)net.minecraftforge.network.NetworkHooks.openScreen((net.minecraft.server.level.ServerPlayer)player,new net.minecraft.world.SimpleMenuProvider((id,inv,p)->new GolemWorkbenchMenu(id,inv,pos),net.minecraft.network.chat.Component.translatable("block.automagy.golem_workbench")),pos);return net.minecraft.world.InteractionResult.sidedSuccess(level.isClientSide);}
 @Override public net.minecraft.world.InteractionResult onWandUseFirst(net.minecraft.world.item.ItemStack wand,net.minecraft.world.item.context.UseOnContext c){if(c.getPlayer()==null||!c.getPlayer().mayBuild()||!c.getPlayer().isShiftKeyDown()||c.getClickedFace().getAxis()==net.minecraft.core.Direction.Axis.Y)return net.minecraft.world.InteractionResult.PASS;if(!c.getLevel().isClientSide&&c.getLevel().getBlockEntity(c.getClickedPos()) instanceof GolemWorkbenchBlockEntity tile){int id=tile.removeUpgrade(c.getClickedFace().get3DDataValue()-2);if(Content.WORKBENCH_UPGRADES.containsKey(id))Block.popResource(c.getLevel(),c.getClickedPos(),new net.minecraft.world.item.ItemStack(Content.WORKBENCH_UPGRADES.get(id).get()));}return net.minecraft.world.InteractionResult.sidedSuccess(c.getLevel().isClientSide);}
 @Override public net.minecraft.world.phys.shapes.VoxelShape getShape(BlockState state,net.minecraft.world.level.BlockGetter world,BlockPos pos,net.minecraft.world.phys.shapes.CollisionContext context){return Block.box(0,0,0,16,8,16);}
 @Override public RenderShape getRenderShape(BlockState s){return RenderShape.MODEL;}
 @Override public BlockEntity newBlockEntity(BlockPos pos,BlockState s){return new GolemWorkbenchBlockEntity(pos,s);}
 @Override public <T extends BlockEntity> BlockEntityTicker<T> getTicker(Level level,BlockState state,BlockEntityType<T> type){return level.isClientSide?null:createTickerHelper(type,Content.GOLEM_WORKBENCH_TILE.get(),GolemWorkbenchBlockEntity::tick);}
 @Override public void onRemove(BlockState state,Level level,BlockPos pos,BlockState next,boolean moving){if(!state.is(next.getBlock())&&level.getBlockEntity(pos) instanceof GolemWorkbenchBlockEntity tile)tile.dropContents();super.onRemove(state,level,pos,next,moving);}
}
